import useGetVaultsFarmingApr from '@/hooks/vaults-farming/useGetVaultsFarmingApr'
import useVaultsListV2Store from '@/store/vaults-v2/useVaultsList'
import { VaultV2ApiInfo } from '@/types/vaultsV2'
import { AddressCopyLink, Block, CetusTooltip, SelectTab, TooltipIcon } from '@cetus/design'
import useExplorer from '@cetus/hooks/src/useExplorer'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CoinPairImage, HTextLabelBox } from '@cetus/ui-kit'
import { symbolDataDisplayProcessing } from '@cetus/utils'
import { Center, HStack, Stack, Text, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import PoweredByHaedal from '../common/PoweredByHaedal'
import VaultsFarmIcon from '../common/VaultsFarmIcon'
import { VaultsAprTooltipContent } from '../list/common/VaultsAprBlock'
import { CoinImage } from '../list/common/VaultsRewardsBlock'

type VaultsHeaderProps = {
  apiVaultInfo: VaultV2ApiInfo
  vaultTvl: string
  performanceFee: string
  vaultTabList: any
  vaultCurrTab: string
  setVaultCurrTab: (item: any) => void
}

export function VaultsHeader({ apiVaultInfo, vaultTvl, performanceFee, vaultTabList, vaultCurrTab, setVaultCurrTab }: VaultsHeaderProps) {
  const { isApp } = useWindowWidth()
  const { getExplorerUrl } = useExplorer()

  const { vaultsFarmsRewardObj } = useVaultsListV2Store()
  console.log('🚀🚀🚀 ~ VaultsListItemPC.tsx:26 ~ vaultsFarmsRewardObj:', vaultsFarmsRewardObj)
  const currentVaultsFarmsReward = useMemo(() => {
    return vaultsFarmsRewardObj[apiVaultInfo?.vaultId]
  }, [vaultsFarmsRewardObj, apiVaultInfo?.vaultId])

  const isVaultsFarming = useMemo(() => {
    return currentVaultsFarmsReward?.isVaultsFarming
  }, [currentVaultsFarmsReward])
  console.log('🚀🚀🚀 ~ VaultsBanner.tsx:42 ~ isVaultsFarming ~ isVaultsFarming:', isVaultsFarming)
  const { getVaultsFarmingApr } = useGetVaultsFarmingApr(currentVaultsFarmsReward)

  const { vaultFarmingAprDisplay } = getVaultsFarmingApr()
  return (
    <Stack mb="16px" flexDir={{ base: 'column', lg: 'row' }} w="100%" alignItems="flex-end" justifyContent="space-between">
      <VStack w={{ base: '100%', lg: 'unset' }} gap="4px" align="flex-start">
        {/* 左边区域 */}
        <HStack w={{ base: '100%', lg: 'unset' }}>
          <CoinPairImage
            coinACoinType={apiVaultInfo?.displayTokenA?.coin_type}
            coinBCoinType={apiVaultInfo?.displayTokenB?.coin_type}
            coinAIconUrl={apiVaultInfo?.displayTokenA?.logo_url}
            coinBIconUrl={apiVaultInfo?.displayTokenB?.logo_url}
          />
          <VStack alignItems="start" flexDirection={apiVaultInfo?.category == 'haedal' ? 'column' : 'row'} gap="2px">
            <HStack>
              <Text fontSize="20px" color="text_caption" fontWeight="500">
                {`${apiVaultInfo?.displayTokenA?.symbol || ''} - ${apiVaultInfo?.displayTokenB?.symbol || ''}`}
              </Text>
              <Block w="unset" p="4px 6px" borderRadius="12px" ml="4px">
                <HStack>
                  <Text fontSize="12px" color="primary">
                    {apiVaultInfo?.feeDisplay}
                  </Text>
                </HStack>
              </Block>
              {isVaultsFarming && <VaultsFarmIcon />}
            </HStack>
          </VStack>
        </HStack>
        <HStack w={{ base: '100%', lg: 'unset' }} gap={{ base: '2px', lg: '8px' }}>
          {apiVaultInfo?.category == 'haedal' && <PoweredByHaedal category="haedal" mt="0px" />}
          {!isApp && (
            <HStack gap="4px">
              <Text fontSize="12px" whiteSpace="nowrap">
                Vault Address
              </Text>
              <AddressCopyLink
                fontSize="12px"
                showCopyTooltip={true}
                showLinkTooltip={true}
                address={apiVaultInfo?.vaultId || ''}
                onClickLink={() => {
                  window.open(getExplorerUrl(apiVaultInfo?.vaultId, 'poolAddress'), '_blank')
                }}
              />
            </HStack>
          )}
        </HStack>
        {!isApp && apiVaultInfo?.category == 'haedal' && (
          <SelectTab
            type="borderTab"
            wrapStyle={{
              w: '100%',
              h: '60px',
              bg: 'none',
              border: 'none'
            }}
            itemStyle={{
              fontSize: '16px',
              mr: '28px'
            }}
            tabList={vaultTabList}
            currentTab={vaultCurrTab}
            handleChangeTab={(item: any) => {
              setVaultCurrTab(item?.value)
            }}
          />
        )}
      </VStack>
      {/* 右边区域 */}
      <Stack w={{ base: '100%', lg: 'unset' }} flexDir={{ base: 'column', lg: 'row' }} gap={{ base: '8px', lg: '28px' }}>
        {isApp && (
          <HTextLabelBox
            label="Vault Address"
            labelStyle={{
              fontSize: '14px'
            }}
            value={
              <AddressCopyLink
                fontSize="14px"
                color="text_caption"
                address={apiVaultInfo?.vaultId || ''}
                onClickLink={() => {
                  window.open(getExplorerUrl(apiVaultInfo?.vaultId, 'poolAddress'), '_blank')
                }}
              />
            }
          />
        )}
        <VStack w={{ base: '100%', lg: 'unset' }} justify="space-between" gap="6px" flexDirection={{ base: 'row', lg: 'column' }}>
          {!isApp ? (
            <>
              <Text w="100%" fontSize={{ base: '14px', lg: '12px' }} textAlign={isApp ? 'left' : 'right'}>
                APY
              </Text>
              <CetusTooltip
                placement="bottom"
                tooltip={
                  <VaultsAprTooltipContent
                    vaultsLstApyDisplay={apiVaultInfo?.vaultsLstApyDisplay}
                    vaultsApyDisplay={apiVaultInfo?.vaultsApyDisplay}
                    vaultsTotalApyDisplay={apiVaultInfo?.vaultsTotalApyDisplay}
                    vaultsAprDisplay={apiVaultInfo?.vaultsAprDisplay}
                    category={apiVaultInfo?.category}
                    isVaultsFarming={isVaultsFarming}
                    vaultFarmingAprDisplay={vaultFarmingAprDisplay}
                  />
                }
              >
                <Center>
                  <HStack gap="4px">
                    <Text
                      color="text_highlight"
                      h="20px"
                      cursor="help"
                      textDecoration="underline dotted"
                      textUnderlineOffset="3px"
                      lineHeight="20px"
                      fontWeight="500"
                    >
                      {apiVaultInfo?.category == 'cetus' ? apiVaultInfo?.vaultsTotalApyDisplay : apiVaultInfo?.vaultsApyDisplay || '-'}
                    </Text>
                    {isVaultsFarming && vaultFarmingAprDisplay && (
                      <Text p="2px 8px" bg="primary_yellow_opacity.10" color="primary_yellow" borderRadius="4px" fontSize="12px" h="16px">
                        +{vaultFarmingAprDisplay}
                      </Text>
                    )}
                  </HStack>
                </Center>
              </CetusTooltip>
            </>
          ) : (
            <HTextLabelBox
              wrapStyle={{
                w: '100%',
                gap: '6px'
              }}
              label="APY"
              labelStyle={{
                fontSize: '14px',
                // color: 'text_highlight',
                fontWeight: '500'
              }}
              rightValueTip={
                <VaultsAprTooltipContent
                  vaultsLstApyDisplay={apiVaultInfo?.vaultsLstApyDisplay}
                  vaultsApyDisplay={apiVaultInfo?.vaultsApyDisplay}
                  vaultsTotalApyDisplay={apiVaultInfo?.vaultsTotalApyDisplay}
                  vaultsAprDisplay={apiVaultInfo?.vaultsAprDisplay}
                  vaultFarmingAprDisplay={vaultFarmingAprDisplay}
                  category={apiVaultInfo?.category}
                  isVaultsFarming={isVaultsFarming}
                />
              }
              value={
                <HStack>
                  <HStack>
                    <Text textDecor="underline dotted" color="primary">
                      {apiVaultInfo?.category == 'cetus' ? apiVaultInfo?.vaultsTotalApyDisplay : apiVaultInfo?.vaultsApyDisplay || '-'}
                    </Text>
                  </HStack>
                  {isVaultsFarming && vaultFarmingAprDisplay && (
                    <Text p="2px 4px" bg="primary_yellow_opacity.10" color="primary_yellow" borderRadius="4px" fontSize="12px">
                      +{vaultFarmingAprDisplay}
                    </Text>
                  )}
                </HStack>
              }
              valueStyle={{
                color: 'text_highlight',
                h: '20px',
                lineHeight: '20px',
                fontSize: '14px',
                fontWeight: '500',
                textDecoration: 'none'
              }}
            />
          )}
        </VStack>
        <VStack w={{ base: '100%', lg: 'unset' }} justify="space-between" gap="6px" flexDirection={{ base: 'row', lg: 'column' }}>
          <Text w="100%" fontSize={{ base: '14px', lg: '12px' }} textAlign={isApp ? 'left' : 'right'}>
            Earnings
          </Text>
          <CetusTooltip
            placement="top"
            tooltip={
              <Text fontSize="12px" lineHeight="20px" maxW="240px">
                Rewards will be auto harvested and compounded to your position.
              </Text>
            }
          >
            <Center>
              <HStack justifyContent="end">
                {apiVaultInfo?.vaultsRewards.map(coinType => {
                  return <CoinImage key={coinType} coinType={coinType} />
                })}
              </HStack>
            </Center>
          </CetusTooltip>
        </VStack>
        <VStack w={{ base: '100%', lg: 'unset' }} justify="space-between" gap="6px" flexDirection={{ base: 'row', lg: 'column' }}>
          <Text w="100%" fontSize={{ base: '14px', lg: '12px' }} textAlign={isApp ? 'left' : 'right'}>
            TVL
          </Text>
          <Text color="text_caption" h="20px" lineHeight="20px" fontWeight="500">
            {(apiVaultInfo?.category == 'haedal' ? symbolDataDisplayProcessing(vaultTvl, '$') : apiVaultInfo?.vaultsTvlDisplay) || '-'}
          </Text>
        </VStack>
        {apiVaultInfo?.category == 'haedal' && (
          <VStack
            w={{ base: '100%', lg: 'unset' }}
            justify="space-between"
            align={{ base: 'center', lg: 'flex-end' }}
            gap="6px"
            flexDirection={{ base: 'row', lg: 'column' }}
          >
            <HStack gap="4px" mt="-4px">
              <Text w="100%" fontSize={{ base: '14px', lg: '12px' }}>
                Performance Fee
              </Text>
              <TooltipIcon maxW="340px" tooltipCon="Commission charged from earned fees and rewards" />
            </HStack>
            <Text color="text_caption" h="20px" lineHeight="20px" fontWeight="500">
              {performanceFee || '-'}
            </Text>
          </VStack>
        )}
      </Stack>
    </Stack>
  )
}
